function h(l,t,n){return l<t?t:l>n?n:l}function u(l){const t=[];for(let n=0;n<l;n+=1)t.push({x:0,y:0,vx:0,vy:0,life:0,max:1,size:1,color:"#fff"});return{list:t,next:0}}function x(l,t,n,i,e,s,o,p=.5,y=2){for(let f=0;f<i;f+=1){const a=l.list[l.next];l.next=(l.next+1)%l.list.length;const c=o()*Math.PI*2,r=e*(.3+o()*.7);a.x=t,a.y=n,a.vx=Math.cos(c)*r,a.vy=Math.sin(c)*r,a.max=p*(.6+o()*.4),a.life=a.max,a.size=y,a.color=s}}function v(l,t,n=0,i=.15){const e=Math.pow(i,t);for(const s of l.list)s.life<=0||(s.life-=t,s.vx*=e,s.vy=s.vy*e+n*t,s.x+=s.vx*t,s.y+=s.vy*t)}function M(l,t){for(const n of t.list){if(n.life<=0)continue;l.globalAlpha=h(n.life/n.max,0,1),l.fillStyle=n.color;const i=n.size;l.fillRect(Math.round(n.x-i/2),Math.round(n.y-i/2),i,i)}l.globalAlpha=1}function S(l,t,n,i=.12){l.globalAlpha=i,l.fillStyle="#000";for(let e=1;e<n;e+=3)l.fillRect(0,e,t,1);l.globalAlpha=1}export{S as a,u as b,h as c,M as d,x as e,v as s};
